const monitorCache = {
  at: 0,
  checkedAt: null,
  targets: [],
};

function parseUrlOrNull(value) {
  try {
    return new URL((value || '').toString().trim());
  } catch (_) {
    return null;
  }
}

function normalizeHostname(value) {
  return (value || '').toString().trim().toLowerCase().replace(/^www\./, '');
}

function deriveSelfProbeUrl(rawUrl) {
  const targetUrl = parseUrlOrNull(rawUrl);
  if (!targetUrl) return null;

  const targetPath = targetUrl.pathname || '/';
  if (!targetPath.startsWith('/health')) return null;

  const publicApiUrl = parseUrlOrNull(process.env.PUBLIC_API_URL || '');
  if (!publicApiUrl) return null;

  if (normalizeHostname(targetUrl.hostname) !== normalizeHostname(publicApiUrl.hostname)) {
    return null;
  }

  const selfProbeBase =
    (process.env.ADMIN_MONITOR_SELF_BASE_URL || '').toString().trim()
    || `http://127.0.0.1:${process.env.PORT || '3000'}`;
  const selfProbeBaseUrl = parseUrlOrNull(selfProbeBase);
  if (!selfProbeBaseUrl) return null;

  const selfUrl = new URL(targetUrl.pathname + targetUrl.search, selfProbeBaseUrl.toString());
  return selfUrl.toString();
}

function uniqueUrls(values) {
  const seen = new Set();
  const out = [];
  for (const value of values) {
    const candidate = (value || '').toString().trim();
    if (!candidate || seen.has(candidate)) continue;
    seen.add(candidate);
    out.push(candidate);
  }
  return out;
}

function deriveTimeoutFallbackUrls(rawUrl) {
  const base = (rawUrl || '').toString().trim();
  if (!base) return [];

  let parsed;
  try {
    parsed = new URL(base);
  } catch (_) {
    return [];
  }

  const currentPath = parsed.pathname || '/';
  if (currentPath !== '/health' && currentPath !== '/health/ready') {
    return [];
  }

  const fallbackPath = currentPath === '/health' ? '/health/ready' : '/health';
  const fallbackUrl = new URL(base);
  fallbackUrl.pathname = fallbackPath;

  const fallbackHref = fallbackUrl.toString();
  return fallbackHref !== base ? [fallbackHref] : [];
}

function parseIntEnv(name, fallback, { min = 0, max = Number.MAX_SAFE_INTEGER } = {}) {
  const raw = parseInt(process.env[name] || '', 10);
  if (!Number.isFinite(raw)) return fallback;
  return Math.max(min, Math.min(max, raw));
}

function parseMonitorTargets() {
  const raw = (process.env.ADMIN_MONITOR_TARGETS || '').toString().trim();
  const fallback = [
    { id: 'kubus.site', label: 'kubus.site', url: 'https://kubus.site' },
    { id: 'art.kubus.site', label: 'art.kubus.site', url: 'https://art.kubus.site' },
    { id: 'app.kubus.site', label: 'app.kubus.site', url: 'https://app.kubus.site' },
    { id: 'api.kubus.site', label: 'api.kubus.site', url: 'https://api.kubus.site/health' },
    { id: 'bapi.kubus.site', label: 'bapi.kubus.site', url: 'https://bapi.kubus.site/health' },
  ];

  if (!raw) return fallback;

  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return fallback;

    const normalized = parsed
      .map((item) => ({
        id: (item?.id || '').toString().trim(),
        label: (item?.label || item?.id || '').toString().trim(),
        url: (item?.url || '').toString().trim(),
      }))
      .filter((item) => item.id && item.url && /^https?:\/\//i.test(item.url));

    return normalized.length > 0 ? normalized : fallback;
  } catch (_) {
    return fallback;
  }
}

async function probeTarget(target, { timeoutMs, retries, degradedMs }) {
  let lastError = null;
  let lastStatus = null;
  const primaryUrl = target.url;
  const selfUrl = deriveSelfProbeUrl(primaryUrl);
  const probeUrls = uniqueUrls([
    selfUrl,
    primaryUrl,
    ...(selfUrl ? deriveTimeoutFallbackUrls(selfUrl) : []),
    ...deriveTimeoutFallbackUrls(primaryUrl),
  ]);

  for (let probeIndex = 0; probeIndex < probeUrls.length; probeIndex += 1) {
    const probeUrl = probeUrls[probeIndex];
    let timedOutOnProbe = false;
    let hadNetworkError = false;

    for (let attempt = 0; attempt <= retries; attempt += 1) {
      const startedAt = Date.now();
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
      try {
        const response = await fetch(probeUrl, {
          method: 'GET',
          redirect: 'follow',
          signal: controller.signal,
          headers: { Accept: 'application/json,text/plain,*/*' },
        });

        clearTimeout(timeoutId);
        const latencyMs = Date.now() - startedAt;
        lastStatus = response.status;

        if (response.ok) {
          return {
            id: target.id,
            label: target.label,
            url: target.url,
            status: latencyMs > degradedMs ? 'degraded' : 'up',
            latencyMs,
            httpStatus: response.status,
            lastError: null,
            checkedUrl: probeUrl,
          };
        }

        if (response.status >= 500) {
          lastError = `HTTP ${response.status}`;
          continue;
        }

        return {
          id: target.id,
          label: target.label,
          url: target.url,
          status: 'degraded',
          latencyMs,
          httpStatus: response.status,
          lastError: `HTTP ${response.status}`,
          checkedUrl: probeUrl,
        };
      } catch (error) {
        clearTimeout(timeoutId);
        const isTimeout = error?.name === 'AbortError';
        timedOutOnProbe = timedOutOnProbe || isTimeout;
        hadNetworkError = true;
        lastError = isTimeout ? 'timeout' : (error?.message || 'request failed');
      }
    }

    // We got an HTTP response on this probe URL (even if non-OK), so don't
    // hide it behind a timeout-only fallback path probe.
    if (lastStatus !== null) {
      break;
    }

    // Only fail over to alternative health path when we had no HTTP status
    // and the primary probe timed out / had a network-level failure.
    if (probeIndex < probeUrls.length - 1 && lastStatus === null && (timedOutOnProbe || hadNetworkError)) {
      continue;
    }
  }

  return {
    id: target.id,
    label: target.label,
    url: target.url,
    status: lastStatus ? 'down' : 'unknown',
    latencyMs: null,
    httpStatus: lastStatus,
    lastError,
    checkedUrl: probeUrls[probeUrls.length - 1] || target.url,
  };
}

async function getMonitorTargets({ refresh = false } = {}) {
  const now = Date.now();
  const ttlMs = parseIntEnv('ADMIN_MONITOR_CACHE_MS', 45000, { min: 5000, max: 5 * 60 * 1000 });
  const timeoutMs = parseIntEnv('ADMIN_MONITOR_TIMEOUT_MS', 6000, { min: 500, max: 30000 });
  const retries = parseIntEnv('ADMIN_MONITOR_RETRIES', 1, { min: 0, max: 3 });
  const degradedMs = parseIntEnv('ADMIN_MONITOR_DEGRADED_MS', 1200, { min: 100, max: 60000 });

  if (!refresh && monitorCache.checkedAt && (now - monitorCache.at) < ttlMs) {
    return {
      cached: true,
      checkedAt: monitorCache.checkedAt,
      targets: monitorCache.targets,
    };
  }

  const targets = parseMonitorTargets();
  const results = await Promise.all(
    targets.map((target) => probeTarget(target, { timeoutMs, retries, degradedMs })),
  );

  monitorCache.at = Date.now();
  monitorCache.checkedAt = new Date(monitorCache.at).toISOString();
  monitorCache.targets = results;

  return {
    cached: false,
    checkedAt: monitorCache.checkedAt,
    targets: monitorCache.targets,
  };
}

module.exports = {
  getMonitorTargets,
};
